        # Reject bools (bool is subclass of int)
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("amount must be an integer")
        if amount <= 0:
            raise ValueError("amount must be a positive integer")

    def seed(self, account_id: str, balance: int):
        # Validate inputs
        self._validate_account_id(account_id, "account_id")
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            raise ValueError("balance must be a non‑negative integer")
        # Insert or replace seed data atomically
        try:
            self.db.execute('BEGIN')
            self.db.execute('INSERT INTO accounts (id, balance) VALUES (?, ?)', (account_id, balance))
            self.db.commit()
        except Exception:
            self.db.rollback()
            raise

    def transfer(self, transfer_id: str, source: str, destination: str, amount: int) -> bool:
        # ---- Parameter validation ----
        if not isinstance(transfer_id, str) or transfer_id == "":
            raise ValueError("transfer_id must be a non‑empty string")
        self._validate_account_id(source, "source")
        self._validate_account_id(destination, "destination")
        self._validate_amount(amount)
        if source == destination:
            raise ValueError("source and destination must be different accounts")

        try:
            self.db.execute('BEGIN')
            # ---- Idempotency check ----
            existing = self.db.execute(
                'SELECT source, destination, amount FROM transfers WHERE id = ?', (transfer_id,)
            ).fetchone()
            if existing:
                # If the existing record matches the request, treat as idempotent success
                if existing[0] == source and existing[1] == destination and existing[2] == amount:
                    self.db.commit()
                    return True
                # Conflict: same transfer_id but different payload
                raise ValueError("conflicting transfer parameters for existing transfer_id")

            # ---- Sufficient funds check ----
            src_row = self.db.execute('SELECT balance FROM accounts WHERE id = ?', (source,)).fetchone()
            if not src_row:
                # Source account does not exist -> treat as insufficient funds
                self.db.rollback()
                return False
            if src_row[0] < amount:
                self.db.rollback()
                return False

            # ---- Destination existence check ----
            dst_row = self.db.execute('SELECT balance FROM accounts WHERE id = ?', (destination,)).fetchone()
            if not dst_row:
                # Destination account missing -> abort transaction
                self.db.rollback()
                raise ValueError("destination account does not exist")

            # ---- Perform atomic balance updates ----
            self.db.execute('UPDATE accounts SET balance = balance - ? WHERE id = ?', (amount, source))
            self.db.execute('UPDATE accounts SET balance = balance + ? WHERE id = ?', (amount, destination))

            # Record the transfer
            self.db.execute(
                'INSERT INTO transfers (id, source, destination, amount, status) VALUES (?,?,?,?,?)',
                (transfer_id, source, destination, amount, 'completed')
            )
            self.db.commit()
            return True
        except sqlite3.IntegrityError as e:
            # Likely a duplicate primary key race – rollback and re‑raise as conflict
            self.db.rollback()
            raise ValueError(str(e))
        except Exception:
            # Any other error triggers a full rollback
            self.db.rollback()
            raise

    def balance(self, account_id: str) -> int:
        row = self.db.execute('SELECT balance FROM accounts WHERE id = ?', (account_id,)).fetchone()
        return row[0] if row else 0

